CREATE TABLE IF NOT EXISTS public.bf4ps_primary_disk_samples (sample_id integer PRIMARY KEY DEFAULT 1 CHECK(sample_id=1),hostname text NOT NULL,available_bytes bigint NOT NULL,total_bytes bigint NOT NULL,free_bytes bigint NOT NULL,sampled_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION public.bf4ps_admin_storage_health() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('disk',(SELECT to_jsonb(d) FROM public.bf4ps_primary_disk_samples d WHERE sample_id=1 AND sampled_at>now()-interval '3 minutes'),'replicas',COALESCE((SELECT jsonb_agg(jsonb_build_object('slot',r.slot_name,'active',r.active,'state',s.state,'address',s.client_addr::text,'unsent_bytes',CASE WHEN s.sent_lsn IS NOT NULL THEN pg_wal_lsn_diff(pg_current_wal_lsn(),s.sent_lsn)::bigint END,'replay_lag_bytes',CASE WHEN s.replay_lsn IS NOT NULL THEN pg_wal_lsn_diff(pg_current_wal_lsn(),s.replay_lsn)::bigint END,'retained_bytes',CASE WHEN r.restart_lsn IS NOT NULL THEN pg_wal_lsn_diff(pg_current_wal_lsn(),r.restart_lsn)::bigint END) ORDER BY r.slot_name) FROM pg_catalog.pg_replication_slots r LEFT JOIN pg_catalog.pg_stat_replication s ON s.pid=r.active_pid WHERE r.slot_type='physical'),'[]'::jsonb))
$$;
REVOKE ALL ON FUNCTION public.bf4ps_admin_storage_health() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.bf4ps_admin_storage_health() TO bf4ps_admin_moderation;
